        /// <summary>Get COMPATIBILITY_VERSION.CONFIG_VERSION.</summary>
        /// <param name="configJson">The configuration JSON (opaque; passed byte-exact).</param>
        /// <returns>The result, as JSON text.</returns>
        /// <remarks>
        /// Result is a JSON string (e.g. "11" in the template). Absent or non-string CONFIG_VERSION (or any missing parent) = NOT_FOUND.
        /// Wire name: <c>get_compatibility_version</c>.
        /// </remarks>
        /// <exception cref="SzConfigToolException">Reason codes: JSON_PARSE, NOT_FOUND (plus the universal wire errors).</exception>
        public static string GetCompatibilityVersion(string configJson)
