        }

        /// <summary>Set COMPATIBILITY_VERSION.CONFIG_VERSION.</summary>
        /// <param name="configJson">The configuration JSON (opaque; passed byte-exact).</param>
        /// <param name="newVersion">Stored verbatim as a JSON string; no format validation.</param>
        /// <returns>The modified configuration JSON.</returns>
        /// <remarks>
        /// Absent CONFIG_BASE_VERSION or COMPATIBILITY_VERSION = NOT_FOUND; COMPATIBILITY_VERSION not an object = INVALID_CONFIG. TRAP: an absent G2_CONFIG is NOT an error — the config is returned unchanged (re-serialized).
        /// Wire name: <c>update_compatibility_version</c>.
        /// </remarks>
        /// <exception cref="SzConfigToolException">Reason codes: JSON_PARSE, NOT_FOUND, INVALID_CONFIG (plus the universal wire errors).</exception>
        public static string UpdateCompatibilityVersion(string configJson, string newVersion)
        {
            var args = new ArgsWriter();
            args.Str("new_version", newVersion, nameof(newVersion));
            return NativeCall.Config("update_compatibility_version", configJson, args.ToJson());
        }

        /// <summary>Compare COMPATIBILITY_VERSION.CONFIG_VERSION with an expected value.</summary>
        /// <param name="configJson">The configuration JSON (opaque; passed byte-exact).</param>
        /// <param name="expectedVersion">Compared by exact, case-sensitive string equality.</param>
        /// <returns>The named result fields CurrentVersion, Matches (each as JSON text).</returns>
        /// <remarks>
        /// Rust returns (current_version, matches) where the String is NOT a config, so it is `json`; tuple_names makes the result the object {"current_version": "11", "matches": true}. Absent CONFIG_VERSION = NOT_FOUND.
        /// Wire name: <c>verify_compatibility_version</c>.
        /// </remarks>
        /// <exception cref="SzConfigToolException">Reason codes: JSON_PARSE, NOT_FOUND (plus the universal wire errors).</exception>
        public static VerifyCompatibilityVersionResult VerifyCompatibilityVersion(string configJson, string expectedVersion)
        {
            var args = new ArgsWriter();
            args.Str("expected_version", expectedVersion, nameof(expectedVersion));
            var r = NativeCall.Json("verify_compatibility_version", configJson, args.ToJson());
            string[] m = NativeCall.Members(r, "current_version", "matches");
            return new VerifyCompatibilityVersionResult(m[0], m[1]);
        }
    }

